{
  "scenario_title": "Daily property tax assessment appeal filings and counter intake across county assessment districts, July to November 2024",
  "data_context": "The County Assessment Appeals Board registry office logged every daily property tax appeal intake event between July and November 2024 to monitor district counter throughput, fee receipts, and applicant caseload progression toward formal board determination.",
  "script": "dim(\"district\", [\"Downtown\", \"North\", \"South\", \"East\"], weights=[0.38, 0.26, 0.20, 0.16], group=\"jurisdiction\")\ndim(\"property_class\", [\"Residential\", \"Commercial\", \"Industrial\", \"Agricultural\"], weights=[0.55, 0.25, 0.12, 0.08], group=\"property\")\ndim(\"appeal_status\", [\"Intake\", \"Verification\", \"Hearing\", \"Determination\"], weights=[0.45, 0.27, 0.18, 0.10], ordered=\"stage\", group=\"workflow\")\n\ntime(\"filing_date\", start=\"2024-07-01\", end=\"2024-11-30\", freq=\"daily\")\n\nmeasure(\"filing_fee_usd\", \"{Residential: 50, Commercial: 200, Industrial: 350, Agricultural: 100}[property_class] + uniform(-5, 5)\", unit=\"USD\", additive=True)\nmeasure(\"disputed_assessment_k_usd\", \"lognormal(3.5 + 0.8 * [property_class=Commercial] + 1.2 * [property_class=Industrial] + 0.3 * [district=Downtown], 0.45)\", unit=\"kUSD\", additive=True)\nmeasure(\"counter_duration_minutes\", \"gamma(4.0, 3.0) + 5.0 * [property_class=Commercial] + 8.0 * [property_class=Industrial]\", unit=\"minutes\", additive=True)\n\nemit(380)\n",
  "intents": [
    {
      "sentence": "Assess the attrition of appeal filings across sequential workflow stages from counter intake to board determination",
      "columns": [
        "appeal_status"
      ],
      "aggregate": "COUNT",
      "family": "process"
    },
    {
      "sentence": "Compare the total filing fees collected across property classes",
      "columns": [
        "property_class",
        "filing_fee_usd"
      ],
      "aggregate": "SUM",
      "family": "comparison"
    },
    {
      "sentence": "Track the daily trend in total disputed assessment valuation across the filing window",
      "columns": [
        "filing_date",
        "disputed_assessment_k_usd"
      ],
      "aggregate": "SUM",
      "family": "trend"
    },
    {
      "sentence": "Examine the relationship between counter processing duration and disputed assessment value",
      "columns": [
        "counter_duration_minutes",
        "disputed_assessment_k_usd"
      ],
      "aggregate": "NONE",
      "family": "relation"
    }
  ]
}
